#include <stdio.h>

int main() {
    FILE *fp;

    fp = fopen("data.txt", "w");
    if (fp) {
        fprintf(fp, "Hello File!");
        fclose(fp);
    }

    fp = fopen("data.txt", "a");
    if (fp) {
        fprintf(fp, " Append me.");
        fclose(fp);
    }

    fp = fopen("data.txt", "r");
    char buffer[50];
    if (fp) {
        fgets(buffer, 50, fp);
        printf("Read: %s\n", buffer);
        fclose(fp);
    }

    return 0;
}
